from itertools import combinations
from functools import lru_cache
from pathlib import Path

# Faces encoded as integer masks; a pure complex by its facet masks.
def bits(x):
    while x:
        b=x&-x; yield b; x-=b

def subfaces(x):
    s=x
    while True:
        yield s
        if s==0: break
        s=(s-1)&x

def maximal(fs):
    fs=set(fs)
    return tuple(sorted(f for f in fs if not any(f!=g and f&g==f for g in fs)))

@lru_cache(None)
def kd_order(fs,k):
    if len(fs)==1: return fs
    size=fs[0].bit_count()
    if any(f.bit_count()!=size for f in fs): return None
    faces=set().union(*(set(subfaces(f)) for f in fs))
    for s in sorted(faces):
        if not s or s.bit_count()>k+1: continue
        dfs=maximal(g for g in faces if g&s!=s)
        if not dfs or any(g.bit_count()!=size for g in dfs): continue
        lfs=maximal(f^s for f in fs if f&s==s)
        do=kd_order(dfs,k)
        if do is None: continue
        lo=kd_order(lfs,k)
        if lo is not None: return do+tuple(s|g for g in lo)
    return None

def skel(fs,size):
    return maximal(s for f in fs for s in subfaces(f) if s.bit_count()<=size)

def check():
    n=5; k=1; count=0; skeletons=0; cone_steps=0
    facets=[sum(1<<v for v in c) for c in combinations(range(n),3)]
    for state in range(1,1<<len(facets)):
        fs=tuple(sorted(f for i,f in enumerate(facets) if state>>i&1))
        order=kd_order(fs,k)
        if order is None: continue
        count+=1
        for i in range(1,len(order)+1):
            assert kd_order(tuple(sorted(order[:i])),k) is not None
        for size in range(1,4):
            assert kd_order(skel(fs,size),k) is not None
            skeletons+=1
        link=skel(fs,2)
        link_order=kd_order(link,k)
        new=1<<n
        current=set(fs)
        for f in link_order:
            current.add(new|f)
            assert kd_order(tuple(sorted(current)),k) is not None
            cone_steps+=1
    return dict(pure_2_complexes_tested=(1<<len(facets))-1,k_decomposable=count,skeleton_checks=skeletons,cone_addition_checks=cone_steps)
if __name__=='__main__':
    print(check())

from functools import lru_cache
from itertools import combinations

def subs(s):
    x=s
    while True:
        yield x
        if not x: break
        x=(x-1)&s

def faces(facets):
    return frozenset(g for f in facets for g in subs(f))

def maximal(fs):
    return tuple(sorted(g for g in fs if not any(g != h and g & h == g for h in fs)))

def pure(facets):
    return bool(facets) and len({f.bit_count() for f in facets}) == 1

@lru_cache(None)
def kd(facets,k):
    if len(facets)==1: return True
    fs=faces(facets)
    dim=facets[0].bit_count()-1
    for s in fs:
        if not s or s.bit_count()>k+1: continue
        dele=maximal(frozenset(g for g in fs if g&s!=s))
        if not pure(dele) or dele[0].bit_count()!=dim+1: continue
        link=maximal(frozenset(g^s for g in fs if g&s==s))
        if kd(dele,k) and kd(link,k): return True
    return False

@lru_cache(None)
def shell(facets):
    if len(facets)==1:return True
    d=facets[0].bit_count()-1
    for f in facets:
        rest=tuple(g for g in facets if g!=f)
        inter=maximal(faces(rest)&frozenset(subs(f)))
        if pure(inter) and inter[0].bit_count()==d and shell(rest):return True
    return False

if __name__=='__main__':
    for n,d in [(5,2),(5,3)]:
        allf=[sum(1<<v for v in c) for c in combinations(range(n),d+1)]
        N=0;S=0
        for a in range(1,1<<len(allf)):
            fac=tuple(sorted(allf[j] for j in range(len(allf)) if a>>j&1))
            ss=shell(fac); kk=kd(fac,d)
            assert ss==kk,(n,d,fac,ss,kk)
            N+=1;S+=ss
        print('n=',n,'d=',d,'families=',N,'shellable= d-decomposable=',S)

