from itertools import combinations
from random import Random
from pathlib import Path
import time,json

def search(n,d,trials,seed):
    rng=Random(seed)
    faces=[sum(1<<i for i in x) for s in range(d+1) for x in combinations(range(n),s)]
    idx={f:i for i,f in enumerate(faces)}
    facets=[sum(1<<i for i in x) for x in combinations(range(n),d+1)]
    bds=[]; cover=[]; ridgebits=[]
    for F in facets:
        bds.append(sum(1<<idx[G] for G in faces if G&F==G))
        ridges=[F^(1<<i) for i in range(n) if F>>i&1]
        ridgebits.append([1<<idx[G] for G in ridges])
        cls=[sum(1<<idx[G] for G in faces if G&R==G) for R in ridges]
        cv=[]
        for p in range(1<<(d+1)):
            z=0
            for j in range(d+1):
                if p>>j&1:z|=cls[j]
            cv.append(z)
        cover.append(cv)
    best=len(facets); start=time.time()
    for trial in range(trials):
        order=[rng.randrange(len(facets))]; old=bds[order[0]]
        remain=list(set(range(len(facets)))-set(order))
        while remain:
            allowed=[]
            for j in remain:
                p=0
                for i,r in enumerate(ridgebits[j]):
                    if old&r:p|=1<<i
                if p and (old&bds[j])==cover[j][p]:allowed.append(j)
            if not allowed:
                if len(remain)<best: best=len(remain)
                result={'n':n,'d':d,'trial':trial,'facets_indices':order,'remaining':remain,'facets':facets}
                Path('workspace/agent3_stuck.json').write_text(json.dumps(result))
                print('FOUND',n,d,trial,len(order),len(remain),flush=True)
                return result
            j=rng.choice(allowed); order.append(j);old|=bds[j];remain.remove(j)
        if (trial+1)%1000==0: print(n,'completed',trial+1,'seconds',round(time.time()-start,2),flush=True)
    print('No stuck shelling',n,d,trials,'seconds',time.time()-start,flush=True)
    return None

